mapper.select:
SELECT * FROM dataset_discovery_candidate WHERE 1 = 1 AND registered_dataset_id IS NULL AND node_id = #{nodeId}
AND (file_name LIKE CONCAT('%', #{query}, '%') OR file_path LIKE CONCAT('%', #{query}, '%'))
ORDER BY last_seen_at DESC, candidate_id DESC

mapper.update:
UPDATE dataset_discovery_candidate
SET registered_dataset_id = #{datasetId}
WHERE candidate_id = #{candidateId}

UPDATE dataset_discovery_candidate
SET availability = #{availability}, updated_at = UTC_TIMESTAMP(3)
WHERE node_id = #{nodeId} AND file_path = #{filePath}

mapper.select:
SELECT * FROM registered_dataset WHERE deleted_at IS NULL AND status = #{status}
AND (dataset_code LIKE CONCAT('%', #{query}, '%') OR name LIKE CONCAT('%', #{query}, '%'))
ORDER BY updated_at DESC, dataset_id DESC

SELECT COUNT(*) FROM migration_task
WHERE (registered_dataset_id = #{datasetId}

        OR (registered_dataset_id IS NULL AND data_id = #{legacyDataId})

) AND status NOT IN ('COMPLETED', 'FAILED')

